import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useSelector } from 'react-redux';
import LandingNavbar from '../components/LandingNavbar';
import Navbar from '../components/Navbar';

const Gallery = () => {
  const [filter, setFilter] = useState('all');
  const { user } = useSelector((state) => state.auth);

  // Dummy data for demonstration
  const artworks = [
    { id: 1, title: 'Traditional Dance', artist: 'Jean Paul', category: 'painting', price: '$450', image: 'https://picsum.photos/400/300' },
    { id: 2, title: 'Modern Rwanda', artist: 'Marie Claire', category: 'digital', price: '$350', image: 'https://picsum.photos/400/301' },
    { id: 3, title: 'Village Life', artist: 'Emmanuel', category: 'sculpture', price: '$550', image: 'https://picsum.photos/400/302' },
    { id: 4, title: 'Urban Dreams', artist: 'Alice', category: 'painting', price: '$400', image: 'https://picsum.photos/400/303' },
    { id: 5, title: 'Nature\'s Call', artist: 'Patrick', category: 'photography', price: '$300', image: 'https://picsum.photos/400/304' },
    { id: 6, title: 'Cultural Heritage', artist: 'Sarah', category: 'sculpture', price: '$600', image: 'https://picsum.photos/400/305' },
  ];

  const filteredArtworks = filter === 'all' ? artworks : artworks.filter(art => art.category === filter);

  return (
    <div className="min-h-screen bg-cream">
      {user ? <Navbar userType={user.role.toLowerCase()} /> : <LandingNavbar />}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <h1 className="text-3xl font-bold text-brown mb-8">Gallery</h1>

        {/* Filter Section */}
        <div className="mb-8">
          <div className="flex space-x-4">
            <button
              onClick={() => setFilter('all')}
              className={`px-4 py-2 rounded-lg ${
                filter === 'all' ? 'bg-coral text-white' : 'bg-white text-brown hover:bg-brown/5'
              }`}
            >
              All
            </button>
            <button
              onClick={() => setFilter('painting')}
              className={`px-4 py-2 rounded-lg ${
                filter === 'painting' ? 'bg-coral text-white' : 'bg-white text-brown hover:bg-brown/5'
              }`}
            >
              Paintings
            </button>
            <button
              onClick={() => setFilter('sculpture')}
              className={`px-4 py-2 rounded-lg ${
                filter === 'sculpture' ? 'bg-coral text-white' : 'bg-white text-brown hover:bg-brown/5'
              }`}
            >
              Sculptures
            </button>
            <button
              onClick={() => setFilter('photography')}
              className={`px-4 py-2 rounded-lg ${
                filter === 'photography' ? 'bg-coral text-white' : 'bg-white text-brown hover:bg-brown/5'
              }`}
            >
              Photography
            </button>
            <button
              onClick={() => setFilter('digital')}
              className={`px-4 py-2 rounded-lg ${
                filter === 'digital' ? 'bg-coral text-white' : 'bg-white text-brown hover:bg-brown/5'
              }`}
            >
              Digital Art
            </button>
          </div>
        </div>

        {/* Artworks Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredArtworks.map((artwork) => (
            <div key={artwork.id} className="bg-white rounded-lg shadow-md overflow-hidden">
              <img
                src={artwork.image}
                alt={artwork.title}
                className="w-full h-48 object-cover"
              />
              <div className="p-4">
                <h3 className="text-lg font-semibold text-brown">{artwork.title}</h3>
                <p className="text-brown/70">by {artwork.artist}</p>
                <div className="flex justify-between items-center mt-2">
                  <span className="text-coral font-semibold">{artwork.price}</span>
                  <Link
                    to="/login"
                    className="text-coral hover:text-salmon"
                  >
                    View Details
                  </Link>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Gallery;
